export const code = async (inputs) => {
  const companies_raw = inputs.companies_raw || [];
  const party_raw = inputs.party_raw || [];
  const companies = [];
  for (let i = 1; i < companies_raw.length; i++) {
    if (companies_raw[i][0] && companies_raw[i][1]) {
      companies.push({companyID: companies_raw[i][0], tallyCompanyName: companies_raw[i][1]});
    }
  }
  const existingGUIDs = new Map();
  const existingPartyIDs = [];
  for (let i = 1; i < party_raw.length; i++) {
    if (party_raw[i][16]) existingGUIDs.set(party_raw[i][16], {rowNumber: i+1, PartyID: party_raw[i][0], CompanyID: party_raw[i][1], PartyName: party_raw[i][2], PartyType: party_raw[i][3], GroupID: party_raw[i][4], ContactPerson: party_raw[i][5], Phone: party_raw[i][6], Email: party_raw[i][7], Address: party_raw[i][8], GSTIN: party_raw[i][9], OpeningBalance: parseFloat(party_raw[i][10])||0, CreditLimit: parseFloat(party_raw[i][11])||0, CreditDays: parseInt(party_raw[i][12])||0, CreatedAt: party_raw[i][13], UpdatedAt: party_raw[i][14], Version: parseInt(party_raw[i][15])||1, TallyGUID: party_raw[i][16]});
    if (party_raw[i][0]) existingPartyIDs.push(party_raw[i][0]);
  }
  Storage.set('accumulatedNew', []);
  Storage.set('accumulatedUpd', []);
  Storage.set('existingGUIDsMap', Array.from(existingGUIDs.entries()));
  Storage.set('existingPartyIDs', existingPartyIDs);
  Storage.set('companies', companies);
  Storage.set('groupMap', [['Sundry Debtors','GRP-0001'],['Sundry Creditors','GRP-0002']]);
  return {companiesCount: companies.length, existingCount: existingGUIDs.size, companies};
};

export const code = async (inputs) => {
  const xml = inputs.xml || '';
  const ledgers = [];
  const regex = /<LEDGER[^>]*>([\s\S]*?)<\/LEDGER>/gi;
  let match;
  while ((match = regex.exec(xml)) !== null) {
    const ledgerXml = match[1];
    const getTag = (tag) => {
      const r = new RegExp(`<${tag}[^>]*>([\s\S]*?)<\/${tag}>`, 'i');
      const m = ledgerXml.match(r);
      return m ? m[1].trim() : '';
    };
    const addrLines = [];
    const addrRegex = /<ADDRESS[^>]*>([\s\S]*?)<\/ADDRESS>/gi;
    let addrMatch;
    while ((addrMatch = addrRegex.exec(ledgerXml)) !== null) addrLines.push(addrMatch[1].trim());
    ledgers.push({
      guid: getTag('GUID'),
      name: getTag('NAME'),
      parent: getTag('PARENT'),
      address: addrLines.join(', '),
      email: getTag('EMAIL'),
      mobile: getTag('LEDGERMOBILE') || getTag('PARTYMOBILE'),
      gstin: getTag('LEDGERGSTIN') || getTag('PARTYGSTIN'),
      openingBalance: parseFloat(getTag('OPENINGBALANCE')) || 0,
      creditLimit: parseFloat(getTag('CREDITLIMIT')) || 0,
      creditPeriod: parseInt((getTag('CREDITPERIOD')||'').match(/\d+/)||['0']) || 0,
      source: 'Debtor'
    });
  }
  return {ledgers, count: ledgers.length};
};

