export const code = async (inputs) => {
  const debtors = inputs.debtors || [];
  const creditors = inputs.creditors || [];
  const companyID = inputs.companyID;
  const existingGUIDs = new Map(Storage.get('existingGUIDsMap') || []);
  const existingPartyIDs = Storage.get('existingPartyIDs') || [];
  const groupMap = new Map(Storage.get('groupMap') || []);
  const SIGN_FLIP = Storage.get('SIGN_FLIP') || false;
  const merged = new Map();
  for (const d of debtors) merged.set(d.guid, {...d, partyType: 'Customer'});
  for (const c of creditors) {
    if (merged.has(c.guid)) merged.get(c.guid).partyType = 'Both';
    else merged.set(c.guid, {...c, partyType: 'Supplier'});
  }
  const newRows = [], updatedRows = [];
  let maxID = existingPartyIDs.filter(id=>id&&id.startsWith('PTY-')).map(id=>parseInt(id.replace('PTY-',''))).reduce((a,b)=>Math.max(a,b),0);
  const genID = () => { maxID++; return `PTY-${maxID.toString().padStart(4,'0')}`; };
  const now = () => new Date().toISOString().replace('T',' ').substring(0,19);
  const deriveType = (p,e) => { const s=(p||'').toLowerCase(); return s.includes('debtor')?'Customer':s.includes('creditor')?'Supplier':e==='Both'?'Both':'Unclassified'; };
  for (const [guid, t] of merged) {
    const existing = existingGUIDs.get(guid);
    if (!existing) {
      newRows.push({
        PartyID: genID(), CompanyID: companyID, PartyName: t.name, PartyType: deriveType(t.parent,t.partyType), GroupID: groupMap.get(t.parent)||'', ContactPerson: '', Phone: t.mobile, Email: t.email, Address: t.address, GSTIN: t.gstin, OpeningBalance: SIGN_FLIP?-t.openingBalance:t.openingBalance, CreditLimit: t.creditLimit, CreditDays: t.creditPeriod, CreatedAt: now(), UpdatedAt: now(), Version: 1, TallyGUID: guid
      });
    } else {
      const changes = t.name!==existing.PartyName || deriveType(t.parent,t.partyType)!==existing.PartyType || (groupMap.get(t.parent)||'')!==existing.GroupID || (t.mobile||'')!==(existing.Phone||'') || t.address!==existing.Address || (t.gstin||'')!==existing.GSTIN;
      if (changes) {
        updatedRows.push({
          rowNumber: existing.rowNumber, PartyID: existing.PartyID, CompanyID: existing.CompanyID, PartyName: t.name, PartyType: deriveType(t.parent,t.partyType), GroupID: groupMap.get(t.parent)||existing.GroupID, ContactPerson: existing.ContactPerson, Phone: t.mobile, Email: t.email, Address: t.address, GSTIN: t.gstin||existing.GSTIN, OpeningBalance: SIGN_FLIP?-t.openingBalance:t.openingBalance, CreditLimit: t.creditLimit, CreditDays: t.creditPeriod, CreatedAt: existing.CreatedAt, UpdatedAt: now(), Version: existing.Version+1, TallyGUID: guid
        });
      }
    }
  }
  Storage.set('accumulatedNew', [...(Storage.get('accumulatedNew')||[]), ...newRows]);
  Storage.set('accumulatedUpd', [...(Storage.get('accumulatedUpd')||[]), ...updatedRows]);
  Storage.set('existingPartyIDs', [...existingPartyIDs, ...newRows.map(r=>r.PartyID)]);
  return {new: newRows.length, updated: updatedRows.length};
};

export const code = async (inputs) => {
  const newRows = Storage.get('accumulatedNew') || [];
  const updRows = Storage.get('accumulatedUpd') || [];
  const TEST_MODE = Storage.get('TEST_MODE') === true;
  const rowsForAppend = newRows.map(r => [r.PartyID, r.CompanyID, r.PartyName, r.PartyType, r.GroupID, r.ContactPerson, r.Phone, r.Email, r.Address, r.GSTIN, r.OpeningBalance, r.CreditLimit, r.CreditDays, r.CreatedAt, r.UpdatedAt, r.Version, r.TallyGUID]);
  const batchUpdates = updRows.map(r => ({
    updateCells: {
      range: {sheetId: {{PARTY_SHEET_GID}}, startRowIndex: r.rowNumber-1, endRowIndex: r.rowNumber, startColumnIndex: 0, endColumnIndex: 17},
      rows: [{values: [r.PartyID, r.CompanyID, r.PartyName, r.PartyType, r.GroupID, r.ContactPerson, r.Phone, r.Email, r.Address, r.GSTIN, r.OpeningBalance, r.CreditLimit, r.CreditDays, r.CreatedAt, r.UpdatedAt, r.Version, r.TallyGUID].map(v => ({userEnteredValue: typeof v==='number' ? {numberValue:v} : {stringValue:String(v)}}))}],
      fields: '*'
    }
  }));
  return {testMode: TEST_MODE, newCount: newRows.length, updCount: updRows.length, rowsForAppend, batchUpdates};
};
